declare(strict_types=1);require __DIR__.'/bootstrap.php';if(isset($_SESSION['portal_user'])){header('Location:portal.php');exit;}$error='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){verify_csrf();$email=trim((string)($_POST['email']??''));$slug=trim((string)($_POST['company']??''));$st=db()->prepare('SELECT p.*,c.name company_name FROM v10_portal_users p JOIN companies c ON c.id=p.company_id WHERE p.email=? AND c.slug=? AND p.active=1 LIMIT 1');$st->execute([$email,$slug]);$p=$st->fetch();if($p&&password_verify((string)($_POST['password']??''),$p['password_hash'])){session_regenerate_id(true);$_SESSION['portal_user']=['id'=>(int)$p['id'],'company_id'=>(int)$p['company_id'],'customer_id'=>(int)$p['customer_id'],'email'=>$p['email'],'company_name'=>$p['company_name']];header('Location:portal.php');exit;}$error='Invalid company, email, or password.';}
